      <span className="text-xs text-muted-foreground shrink-0 mt-0.5">
        {item.time}
      </span>
    </div>
  );
}

interface AnimatedListDemoProps {
  maxVisible?: number;
  gap?: number;
  animation?: AnimationType;
}

export const AnimatedListDemo = ({
  maxVisible = 8,
  gap = 12,
  animation = "scale",
}: AnimatedListDemoProps) => {
  const [items, setItems] = React.useState<Notification[]>(
    NOTIFICATIONS.slice(0, 3),
  );
  const counterRef = React.useRef(100);

  React.useEffect(() => {
    const pool = [...NOTIFICATIONS];
    let poolIndex = 0;

    const interval = setInterval(() => {
      const source = pool[poolIndex % pool.length];
      poolIndex++;
      const newItem: Notification = {
        ...source,
        id: counterRef.current++,
        time: "just now",
      };
      setItems((prev) => [newItem, ...prev].slice(0, maxVisible));
    }, 2000);

    return () => clearInterval(interval);
  }, [maxVisible]);

  return (
    <div className="w-full max-w-sm mx-auto p-4">
      <AnimatedList
        items={items}
        renderItem={(item) => <NotificationItem item={item} />}
        maxVisible={maxVisible}
        gap={gap}
        animation={animation}
      />
    </div>
  );
};



export default function DefaultDemo() { return <AnimatedListDemo />; }

