export default function HighlightTextareaDemo({ autoplay = true, bare = false, text, max = 120, speed = 1 }: DemoProps) {
  const [value, setValue] = React.useState(text ?? "");
  const [tokens, setTokens] = React.useState([] as HighlightMatch[]);
  const [motion, setMotion] = React.useState({ ready: false, reduced: true });
