  const ms = (at: number) => Math.round(at * speed);

  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setMotion({ ready: true, reduced: media.matches });
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);

  React.useEffect(() => {
    if (!motion.ready || !autoplay || motion.reduced || paused || text !== undefined) return;
    const timers: number[] = [];
    for (let i = 1; i <= SAMPLE.length; i += 1) timers.push(window.setTimeout(() => setValue(SAMPLE.slice(0, i)), ms(400 + (i - 1) * 42)));
    timers.push(window.setTimeout(() => { setValue(""); setRun((previous) => previous + 1); }, ms(400 + SAMPLE.length * 42 + 2600)));
    return () => timers.forEach((timer) => window.clearTimeout(timer));
  }, [motion.ready, motion.reduced, autoplay, paused, run, text, speed]);

