    };
    frame = requestAnimationFrame(tick);
    timers.push(window.setTimeout(() => (retryRef.current?.querySelector("[data-retry]") as HTMLButtonElement | null)?.click(), ms(3000)));
    timers.push(window.setTimeout(() => { setDeploy(0); failed.current = false; setImported(0); setImportStatus("running"); setEvents([]); setRun((previous) => previous + 1); }, ms(9600)));
    return () => { cancelAnimationFrame(frame); timers.forEach((timer) => window.clearTimeout(timer)); };
  }, [motion.ready, motion.reduced, autoplay, paused, run, preset, speed]);

  React.useEffect(() => {
    if (importStatus !== "running" || imported >= 100) return;
    let frame = 0;
    const from = imported; const start = performance.now();
    const firstPass = !failed.current;
    const target = firstPass ? 42 : 100;
    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / ms(firstPass ? 1300 : 2500));
      setImported(Math.round((from + (target - from) * t) * 10) / 10);
      if (t < 1) frame = requestAnimationFrame(tick);
      else if (firstPass) { failed.current = true; setImportStatus("error"); }
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [importStatus, run]);

  const takeOver = () => autoplay && setPaused(true);

  return (
    <main className="flex min-h-svh w-full flex-col items-center justify-center gap-5 bg-background px-5 py-6 text-foreground" onPointerDownCapture={takeOver} onKeyDownCapture={takeOver}>
      {!bare && (
        <header className="w-full max-w-[480px]">
          <p className="mb-1 text-[10px] font-medium uppercase tracking-[0.2em] text-muted-foreground">Not just a percentage</p>
          <h1 className="text-[24px] font-semibold leading-tight tracking-tight">Which step, what's next, then done.</h1>
        </header>
      )}
      <section className="w-full max-w-[480px] space-y-6 rounded-3xl border border-border bg-card p-5 shadow-xl shadow-primary/5">
        <div data-job="deploy">
          <div className="mb-2 flex items-baseline justify-between"><p className="text-sm font-medium">Deploy v2.4.0</p><span className="font-mono text-[11px] text-muted-foreground">production</span></div>
          <StagedProgressBar stages={DEPLOY} value={deploy} collapseOnComplete={collapse} label="Deploy progress" onComplete={() => note("deploy:complete")} />
          {!autoplay && <input type="range" data-scrub aria-label="Deploy progress" min={0} max={100} value={deploy} onChange={(event) => setDeploy(Number(event.target.value))} className="mt-3 h-1.5 w-full cursor-pointer accent-chart-3" />}
        </div>
        <div data-job="import" ref={retryRef}>
          <div className="mb-2 flex items-baseline justify-between"><p className="text-sm font-medium">Import contacts.csv</p><span className="font-mono text-[11px] text-muted-foreground">2,418 rows</span></div>
          <StagedProgressBar stages={IMPORT} value={imported} status={importStatus === "error" ? "error" : imported >= 100 ? "done" : "running"} errorStageId="scan" collapseOnComplete={collapse} label="Import progress" retryLabel="Retry scan" onRetry={(stage) => { note(`retry:${stage}`); setImportStatus("running"); }} onComplete={() => note("import:complete")} />
        </div>
        <div data-job="agent">
          <div className="mb-2 flex items-baseline justify-between"><p className="text-sm font-medium">Waiting for a build agent</p><span className="font-mono text-[11px] text-muted-foreground">queued</span></div>
          <StagedProgressBar stages={[{ id: "queue", label: "Queue" }, { id: "assign", label: "Assign" }]} size="sm" label="Agent queue" />
        </div>
        <p data-events className="sr-only">{events.join(",")}</p>
      </section>
      {!bare && (
        <footer className="flex w-full max-w-[480px] items-center justify-between text-[10px] text-muted-foreground">
          <span>Sample jobs · nothing is deployed</span>
          <button type="button" data-replay onClick={() => { setDeploy(0); failed.current = !live; setImported(live ? 0 : 42); setImportStatus(live ? "running" : "error"); setEvents([]); setPaused(false); setRun((previous) => previous + 1); }} className="inline-flex items-center gap-1 rounded px-1 underline decoration-border underline-offset-4 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"><RotateCcw className="size-3" aria-hidden="true" />Replay</button>
        </footer>
      )}
    </main>
  );
}

