        <ValidationChecklistInput
          label="Password"
          placeholder="Choose a password"
          type={reveal ? "text" : "password"}
          trailing={<button type="button" data-reveal aria-label={reveal ? "Hide password" : "Show password"} aria-pressed={reveal} onClick={() => setReveal((previous) => !previous)} className="inline-flex size-8 items-center justify-center rounded-lg text-muted-foreground outline-none transition-colors motion-reduce:transition-none hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring">{reveal ? <EyeOff className="size-4" aria-hidden="true" /> : <Eye className="size-4" aria-hidden="true" />}</button>}
          autoComplete="new-password"
          rules={RULES}
          value={password}
          onChange={setPassword}
          onValidityChange={(ok) => setPasswordOk(ok)}
          onAllPassed={() => setEvents((previous) => [...previous, "password"])}
          description="Use something you don't use anywhere else."
          successLabel="Strong password"
        />
        <ValidationChecklistInput
          label="Handle"
          placeholder="your-handle"
          rules={HANDLE_RULES}
          value={handle}
          onChange={setHandle}
          onValidityChange={(ok) => setHandleOk(ok)}
          onAllPassed={() => setEvents((previous) => [...previous, "handle"])}
          description="This becomes your public URL."
          successLabel="Handle is available"
        />
        <button type="submit" data-submit disabled={!(passwordOk && handleOk)} className="inline-flex h-10 w-full items-center justify-center gap-2 rounded-xl bg-primary text-sm font-medium text-primary-foreground outline-none transition-opacity duration-300 motion-reduce:transition-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card disabled:opacity-40">
          Create account <ArrowRight className="size-4" aria-hidden="true" />
        </button>
        <p data-events className="sr-only">{events.join(",")}</p>
      </form>
      {!bare && (
        <footer className="flex w-full max-w-[440px] items-center justify-between text-[10px] text-muted-foreground">
          <span>Sample form · nothing is submitted</span>
          <button type="button" data-replay onClick={() => { setPassword(""); setHandle(""); setReveal(false); setEvents([]); setPaused(false); setRun((previous) => previous + 1); }} className="inline-flex items-center gap-1 rounded px-1 underline decoration-border underline-offset-4 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"><RotateCcw className="size-3" aria-hidden="true" />Replay</button>
        </footer>
      )}
    </main>
  );
}

