"use client";

import * as React from "react";
import { CreditCard, RotateCcw } from "lucide-react";
import { ResolvingAlertBanner } from "@/components/ui/resolving-alert-banner";

type DemoProps = { autoplay?: boolean; bare?: boolean; failFirst?: boolean; speed?: number };

const wait = (ms: number) => new Promise((resolve) => window.setTimeout(resolve, ms));

export default function ResolvingAlertBannerDemo({ autoplay = true, bare = false, failFirst = true, speed = 1 }: DemoProps) {
  const [run, setRun] = React.useState(0);
  const [paused, setPaused] = React.useState(false);
  const [log, setLog] = React.useState([] as { id: number; text: string }[]);
  const [motion, setMotion] = React.useState({ ready: false, reduced: true });
  const syncAttempts = React.useRef(0);
  const paymentRef = React.useRef(null as HTMLDivElement | null);
  const emailRef = React.useRef(null as HTMLDivElement | null);
  const note = (text: string) => setLog((previous) => [{ id: Date.now() + Math.random(), text }, ...previous].slice(0, 4));
  const ms = (value: number) => Math.round(value * speed);

  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setMotion({ ready: true, reduced: media.matches });
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);

  React.useEffect(() => {
    if (!motion.ready || !autoplay || motion.reduced || paused) return;
    const timers: number[] = [];
    const later = (at: number, callback: () => void) => timers.push(window.setTimeout(callback, ms(at)));
    later(1400, () => (paymentRef.current?.querySelector("[data-action]") as HTMLButtonElement | null)?.click());
    later(4600, () => (emailRef.current?.querySelector("[data-action]") as HTMLButtonElement | null)?.click());
    later(10500, () => { syncAttempts.current = 0; setLog([]); setRun((previous) => previous + 1); });
    return () => timers.forEach((timer) => window.clearTimeout(timer));
  }, [motion.ready, motion.reduced, autoplay, paused, run, speed]);

  const takeOver = () => autoplay && setPaused(true);

  return (
    <main className="flex min-h-svh w-full flex-col items-center justify-center gap-5 bg-background px-5 py-6 text-foreground" onPointerDownCapture={takeOver} onKeyDownCapture={takeOver}>
      {!bare && (
        <header className="w-full max-w-[480px]">
          <p className="mb-1 text-[10px] font-medium uppercase tracking-[0.2em] text-muted-foreground">Alerts that finish the job</p>
          <h1 className="text-[24px] font-semibold leading-tight tracking-tight">Fix it right where it's shown.</h1>
        </header>
      )}
      <section key={run} data-stack className="w-full max-w-[480px] space-y-3">
        <ResolvingAlertBanner
          ref={paymentRef}
          tone="warning"
          icon={<CreditCard className="size-5" aria-hidden="true" />}
          title="Payment failed"
          description="Your card ending in 4242 was declined."
          successTitle="Payment succeeded"
          successDescription="Receipt sent to billing@acme.com."
          expectedMs={ms(2200)}
          collapseOnSuccessMs={ms(1500)}
          action={{ label: "Retry payment", pendingLabel: "Charging…", doneLabel: "Paid", onAction: async () => { note("Payment retried"); await wait(ms(2200)); note("Payment succeeded"); } }}
          onCollapse={() => note("Payment alert dismissed itself")}
        />
        <ResolvingAlertBanner
          ref={emailRef}
          tone="info"
          title="Verify your email"
          description="We need to confirm maria@acme.com before you can invite teammates."
          successTitle="Verification email sent"
          successDescription="Check your inbox for the link."
          expectedMs={ms(1600)}
          collapseOnSuccessMs={ms(1500)}
          action={{ label: "Resend email", pendingLabel: "Sending…", doneLabel: "Sent", onAction: async () => { note("Verification email requested"); await wait(ms(1600)); } }}
          onCollapse={() => note("Email alert dismissed itself")}
        />
        <ResolvingAlertBanner
          tone="destructive"
          title="Sync failed"
          description="3 changes could not reach the server."
          errorTitle="Sync failed again"
          errorDescription="The server is still unreachable. Try once more."
          successTitle="Everything is in sync"
          successDescription="3 changes uploaded."
          expectedMs={ms(1400)}
          collapseOnSuccessMs={ms(1500)}
          dismissible
          onDismiss={() => note("Sync alert dismissed")}
          action={{ label: "Retry sync", pendingLabel: "Syncing…", doneLabel: "Synced", retryLabel: "Retry sync", onAction: async () => {
            syncAttempts.current += 1;
            note(`Sync attempt ${syncAttempts.current}`);
            await wait(ms(1200));
            if (failFirst && syncAttempts.current === 1) throw new Error("offline");
            note("Sync succeeded");
          } }}
          onCollapse={() => note("Sync alert dismissed itself")}
