type DemoProps = { autoplay?: boolean; bare?: boolean; controlled?: boolean; noOutside?: boolean };

const ROLES = ["Viewer", "Editor", "Admin"];

export default function MorphDialogDemo({ autoplay = true, bare = false, controlled = false, noOutside = false }: DemoProps) {
  const [inviteOpen, setInviteOpen] = React.useState(false);
  const [projectOpen, setProjectOpen] = React.useState(false);
  const [role, setRole] = React.useState("Editor");
