  const [run, setRun] = React.useState(0);
  const [paused, setPaused] = React.useState(false);
  const inviteRef = React.useRef(null as HTMLButtonElement | null);
  const cardRef = React.useRef(null as HTMLButtonElement | null);

  React.useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setMotion({ ready: true, reduced: media.matches });
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);

  React.useEffect(() => {
    if (!motion.ready || !autoplay || motion.reduced || paused) return;
    const timers: number[] = [];
    const later = (ms: number, callback: () => void) => timers.push(window.setTimeout(callback, ms));
    later(600, () => inviteRef.current?.click());
    later(2600, () => (document.querySelector("[data-morph-close]") as HTMLButtonElement | null)?.click());
    later(3400, () => cardRef.current?.click());
    later(5500, () => (document.querySelector("[data-morph-close]") as HTMLButtonElement | null)?.click());
    later(7000, () => setRun((previous) => previous + 1));
    return () => timers.forEach((timer) => window.clearTimeout(timer));
