        </header>
      )}
      <div className="w-full max-w-[420px] space-y-3 rounded-3xl border border-border bg-card p-5 shadow-xl shadow-primary/5">
        {ACTIONS.map((action) => {
          const Icon = action.icon;
          return (
            <div key={action.id} className="flex items-center justify-between gap-4">
              <span className="flex min-w-0 items-center gap-2 text-sm text-muted-foreground"><Icon className="size-4 shrink-0" aria-hidden="true" /><span className="truncate">{action.label}</span></span>
              <UndoCountdownButton
                ref={(node) => { refs.current[action.id] = node; }}
                label={action.label}
                variant={action.variant}
                undoWindow={undoWindow}
                {...(controlled ? { state: states[action.id], onStateChange: (state) => setStates((previous) => ({ ...previous, [action.id]: state })) } : {})}
                onStart={() => note(`${action.label} · undo in ${Math.round(undoWindow / 1000)}s`)}
                onCommit={() => note(action.commit)}
                onUndo={() => note(action.undo)}
                className="min-w-[164px]"
              />
            </div>
          );
        })}
        <ul data-log aria-label="Activity" className="mt-2 min-h-[72px] space-y-1 border-t border-border pt-3 text-xs text-muted-foreground">
          {log.length === 0 ? <li className="text-muted-foreground/70">Sample actions · nothing is really sent</li> : log.map((entry) => <li key={entry.id} data-log-entry className="truncate">{entry.text}</li>)}
        </ul>
      </div>
      {!bare && (
        <footer className="flex w-full max-w-[420px] items-center justify-between text-[10px] text-muted-foreground">
          <span>Click once to start, click again to undo</span>
          <button type="button" data-replay onClick={() => { setPaused(false); setLog([]); setRun((previous) => previous + 1); }} className="rounded px-1 underline decoration-border underline-offset-4 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">Replay</button>
        </footer>
      )}
    </main>
  );
}

