] /* QR_MODULES_END */;

type DemoProps = { autoplay?: boolean };

export default function QrCodeScanLoginDemo({ autoplay = true }: DemoProps = {}) {
  const [status, setStatus] = React.useState("waiting" as QrCodeLoginStatus);
  const [passwordOpen, setPasswordOpen] = React.useState(false);
  const [paused, setPaused] = React.useState(false);
  const [reduced, setReduced] = React.useState(true);
  const [ready, setReady] = React.useState(false);
  const [cycle, setCycle] = React.useState(0);
  const [message, setMessage] = React.useState("");
  const playing = autoplay && ready && !reduced && !paused;
  const stop = () => setPaused(true);

  React.useLayoutEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(media.matches);
    update();
    setReady(true);
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);

  React.useEffect(() => {
    if (!playing) return;
    const timers = [
      window.setTimeout(() => setStatus("scanned"), 2600),
      window.setTimeout(() => setStatus("confirmed"), 4400),
      window.setTimeout(() => { setStatus("waiting"); setPasswordOpen(true); }, 6000),
      window.setTimeout(() => { setStatus("waiting"); setPasswordOpen(false); setCycle((value) => value + 1); }, 7200),
    ];
    return () => timers.forEach((timer) => window.clearTimeout(timer));
  }, [playing, cycle]);

  const replay = () => {
    setStatus("waiting");
    setPasswordOpen(false);
    setMessage("");
    setCycle((value) => value + 1);
    setPaused(false);
  };

  return (
    <main data-qr-demo data-playing={playing} data-autoplay={autoplay ? "on" : "off"} className="flex min-h-svh w-full flex-col items-center justify-center gap-4 bg-muted/40 px-5 py-5 text-foreground">
      <div className="flex w-full max-w-[660px] items-center justify-between gap-3 px-1"><p className="text-xs font-medium tracking-tight">Your next session starts here.</p><span className="rounded-full border border-border px-2 py-1 text-[9px] font-medium uppercase tracking-[.16em] text-muted-foreground">Demo</span></div>
      <div className="w-full max-w-[660px]" onPointerDownCapture={stop} onKeyDownCapture={stop}>
        <QrCodeScanLogin
          qrModules={DEMO_QR_MODULES}
          appName="Wayline"
          logo={<svg viewBox="0 0 24 24" fill="none" className="size-6"><path d="m4 7 4 11 4-8 4 8 4-11" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" /></svg>}
          status={status}
          onStatusChange={setStatus}
          codeId={cycle}
          deviceName="iPhone"
          welcomeMessage="Welcome back, Maria"
          autoplay={playing}
          passwordOpen={passwordOpen}
          onPasswordOpenChange={setPasswordOpen}
          onUsePassword={stop}
          onRefresh={() => { setStatus("waiting"); setCycle((value) => value + 1); }}
          onPasswordSubmit={() => setMessage("Demo only · no sign-in request was sent")}
        />
      </div>
      <div className="flex w-full max-w-[660px] items-center justify-between gap-2 px-1 text-[10px] text-muted-foreground">
        <span data-demo-note role="status" className="min-w-0">{message || "Sample workspace · No real sign-in"}</span>
        <div className="flex shrink-0 items-center gap-3">
          {autoplay && !reduced && <button type="button" data-pause aria-label={playing ? "Pause demo" : "Play demo"} onClick={() => playing ? stop() : replay()} className="flex items-center gap-1 rounded p-1 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">{playing ? <Pause className="size-3" aria-hidden="true" /> : <Play className="size-3" aria-hidden="true" />}{playing ? "Pause" : "Play"}</button>}
          <button type="button" data-replay onClick={replay} className="flex items-center gap-1 rounded p-1 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"><RotateCcw className="size-3" aria-hidden="true" />Replay</button>
        </div>
