import * as React from "react";
import ElevatorDoorsGallery from "@/components/ui/elevator-doors-gallery";

// An imagined hotel, illustrated with individually sourced stock photography.
export const ELEVATOR_DEMO_ITEMS = [
  {
    src: "https://cdn.My Ui/assets/mirror/43/43d4272e70e0353b5b91db831ddbc83b38b4bf4c504dd22fa0e0dd8ba5f1707f.jpg",
