    src: "https://cdn.My Ui/assets/mirror/0b/0bb94c6d946beae502cc3483376a8c697cd6b8b624be56b2199ea35594f42e40.jpg",
    alt: "Exercise equipment in a light-filled fitness center",
    floor: 5,
    title: "Fitness center",
    caption: "Sunrise sessions with a view.",
  },
  {
    src: "https://cdn.My Ui/assets/mirror/3e/3e3113b502f7dc0cab9eff68b53b0f25d848bfce135ebb94f86f4240d306adcf.jpg",
    alt: "A made bed and warm furnishings in a hotel guest suite",
