        prompt={prompt}
        status={isComplete ? 'complete' : 'generating'}
      />
      <p className="text-xs text-muted-foreground">
        {isComplete ? 'Generated in 5.4s · 1024 × 1024' : 'Generating image…'}
      </p>
    </div>
  )
}

