import FilterToolbar from "@/components/ui/filter-toolbar";
import * as React from "react";

const fields = [
  { id: "status", label: "Status", options: ["Active", "Paused", "Archived"] },
  { id: "owner", label: "Owner", options: ["You", "Team", "Unassigned"] },
  { id: "priority", label: "Priority", options: ["Low", "Medium", "High"] },
];

export default function FilterToolbarDemo() {
  const [filters, setFilters] = React.useState([
    { id: "status", label: "Status", value: "Active" },
    { id: "owner", label: "Owner", value: "You" },
  ]);

  function addFilter(filter) {
    setFilters((previous) => [
      ...previous.filter((entry) => entry.id !== filter.id),
      filter,
    ]);
  }

  return (
    <div className="w-full max-w-xl p-6">
      <FilterToolbar
        filters={filters}
        onRemove={(id) =>
          setFilters((previous) => previous.filter((entry) => entry.id !== id))
        }
        onClearAll={() => setFilters([])}
        addFilter={{ fields, onAdd: addFilter }}
      />
    </div>
  );
}

