import * as React from "react";
import { Button, DataTable, type ColumnDef } from "@/components/ui/data-table-bulk-actions";
import { Download, Plus } from "lucide-react";

/* Northwind Studio's invoices: 23 rows across seven customers. Sort a
   column, search "vela", select rows for the bulk bar, hide a column, or
   search for something that is not there to see the empty state. */

type Invoice = { number: string; customer: string; date: string; amount: number; status: "paid" | "open" | "failed" };
const CUSTOMERS = ["Northwind Studio", "Vela Labs", "Tallyworks", "Harbor & Co", "Juniper Health", "Ostrom Legal", "Kite Robotics"];
const STATUS: Invoice["status"][] = ["paid", "paid", "open", "paid", "failed", "paid", "open"];
const INVOICES: Invoice[] = Array.from({ length: 23 }, (_, i) => ({
  number: `INV-2026-${String(914 - i).padStart(4, "0")}`,
  customer: CUSTOMERS[i % CUSTOMERS.length],
  date: `${String(28 - (i % 27)).padStart(2, "0")} Sep 2026`,
  amount: [8900, 24900, 2900, 10100, 8900, 49900, 17800][i % 7],
  status: STATUS[i % STATUS.length],
}));
