      <div className="flex items-center gap-3">
        <button
          onClick={() => retarget(24 * 3600)}
          className="rounded-md border border-border px-3 py-1.5 font-mono text-[11px] tracking-[0.1em] text-foreground transition-colors hover:bg-accent"
        >
          T-24H
        </button>
