"use client";

import { StatusBar } from "@/components/ui/status-bar";

function generateData() {
  const days = 45;
  const today = new Date();

  return Array.from({ length: days }, (_, i) => {
    const date = new Date(today);
    date.setDate(today.getDate() - (days - 1 - i));
    const day = date.toISOString().slice(0, 10);

    if (i === 12) {
      return {
        day,
        bar: [
          { status: "success" as const, height: 70 },
          { status: "error" as const, height: 30 },
        ],
        card: [
          { status: "success" as const, value: "70%" },
          { status: "error" as const, value: "30%" },
        ],
        events: [
          {
            id: "inc-1",
            name: "API Response Time Degradation",
            type: "incident" as const,
            from: new Date(`${day}T15:24:00Z`),
            to: new Date(`${day}T17:24:00Z`),
          },
        ],
      };
    }

    if (i === 30) {
      return {
        day,
        bar: [{ status: "info" as const, height: 100 }],
        card: [{ status: "info" as const, value: "100%" }],
        events: [
          {
            id: "maint-1",
            name: "Scheduled Database Maintenance",
            type: "maintenance" as const,
            from: new Date(`${day}T12:24:00Z`),
            to: new Date(`${day}T14:24:00Z`),
          },
        ],
      };
    }

    return {
      day,
      bar: [{ status: "success" as const, height: 100 }],
      card: [{ status: "success" as const, value: "100%" }],
      events: [],
    };
  });
}

export default function StatusBarDemo() {
  const data = generateData();

  return (
    <div className="w-full max-w-2xl p-8">
      <StatusBar data={data} />
    </div>
  );
}

