function useTicker(start: number, step: number, intervalMs: number) {
  const [value, setValue] = useState(start);

  useEffect(() => {
    const id = setInterval(() => {
      setValue((v) => Math.max(0, v + Math.round((Math.random() - 0.38) * step)));
    }, intervalMs);

    return () => clearInterval(id);
  }, [step, intervalMs]);

  return value;
}

function AnimatedNumber({ value }: { value: number }) {
  const motionValue = useMotionValue(value);
  const spring = useSpring(motionValue, {
    damping: 28,
    stiffness: 100,
    mass: 0.8,
  });

  const [display, setDisplay] = useState(value);

  useEffect(() => {
    motionValue.set(value);
  }, [value, motionValue]);

  useEffect(() => {
    return spring.on("change", (latest) => {
      setDisplay(Math.round(latest));
    });
  }, [spring]);

  return <>{display.toLocaleString()}</>;
}

function Sparkline() {
  const points = [18, 22, 19, 28, 26, 34, 31, 40, 37, 46, 42, 52, 48, 58];

  const w = 100;
  const h = 100;
  const max = Math.max(...points);
  const min = Math.min(...points);
  const step = w / (points.length - 1);

  const coords = points.map((point, index) => {
    const x = index * step;
    const y = h - ((point - min) / (max - min)) * (h - 14) - 4;
    return [x, y];
  });

  const line = coords
    .map(([x, y], index) => `${index === 0 ? "M" : "L"}${x},${y}`)
    .join(" ");

  const area = `${line} L${w},${h} L0,${h} Z`;

  const [lastX, lastY] = coords[coords.length - 1];

  return (
    <svg
      viewBox={`0 0 ${w} ${h}`}
      preserveAspectRatio="none"
      style={{
        width: "100%",
        height: "100%",
        overflow: "visible",
      }}
    >
      <motion.path
        d={area}
        fill={COLORS.accent}
        initial={{ opacity: 0 }}
        animate={{ opacity: 0.075 }}
        transition={{
          duration: 1,
          delay: 0.7,
        }}
      />

      <motion.path
        d={line}
        fill="none"
        stroke={COLORS.accent}
        strokeWidth="1.6"
        vectorEffect="non-scaling-stroke"
        strokeLinecap="round"
        strokeLinejoin="round"
        initial={{ pathLength: 0, opacity: 0 }}
        animate={{ pathLength: 1, opacity: 1 }}
        transition={{
          pathLength: {
            duration: 1.3,
            delay: 0.35,
            ease: [0.22, 1, 0.36, 1],
          },
          opacity: {
            duration: 0.3,
            delay: 0.35,
          },
        }}
      />

      <motion.circle
        cx={lastX}
        cy={lastY}
        r="2.6"
        fill={COLORS.accent}
        initial={{ scale: 0 }}
        animate={{
          scale: [1, 1.7, 1],
          opacity: [1, 0.55, 1],
        }}
        transition={{
          scale: {
            duration: 2.8,
            repeat: Infinity,
            ease: "easeInOut",
          },
          opacity: {
            duration: 2.8,
            repeat: Infinity,
            ease: "easeInOut",
          },
          delay: 1.45,
        }}
      />
    </svg>
  );
}

function RingProgress({
