function MentionElement(props: any) {
  const selected = useSelected();
  const focused = useFocused();
  const element = props.element as { value: string };

  return (
    <PlateElement
      {...props}
      className={cn(
        "inline-block rounded-md bg-muted px-1.5 py-0.5 align-baseline font-medium text-sm",
        selected && focused && "ring-2 ring-ring",
      )}
      attributes={{
        ...props.attributes,
        contentEditable: false,
        "data-slate-value": element.value,
        draggable: true,
      }}
    >
      {"@"}
      {element.value}
      {props.children}
    </PlateElement>
  );
}

const onSelectItem = getMentionOnSelectItem();

function MentionInputElement(props: any) {
  const { editor, element } = props;
  const [search, setSearch] = React.useState("");

  return (
    <PlateElement {...props} as="span">
      <InlineCombobox
        value={search}
        element={element}
        setValue={setSearch}
        showTrigger={false}
        trigger="@"
      >
        <span className="inline-block rounded-md bg-muted px-1.5 py-0.5 align-baseline text-sm ring-ring focus-within:ring-2">
          <InlineComboboxInput />
        </span>

        <InlineComboboxContent className="my-1.5">
          <InlineComboboxEmpty>No results</InlineComboboxEmpty>

          <InlineComboboxGroup>
            {MENTIONABLES.map((item) => (
              <InlineComboboxItem
                key={item.key}
                value={item.text}
                onClick={() => onSelectItem(editor, item, search)}
              >
                {item.text}
              </InlineComboboxItem>
            ))}
          </InlineComboboxGroup>
        </InlineComboboxContent>
      </InlineCombobox>

      {props.children}
    </PlateElement>
  );
}

export default function InlineComboboxDemo() {
  const editor = usePlateEditor({
    plugins: [
      MentionPlugin.configure({
        options: {
          triggerPreviousCharPattern: /^$|^[\s"']$/,
        },
      }).withComponent(MentionElement),
      MentionInputPlugin.withComponent(MentionInputElement),
    ],
    value: [
      {
        type: "p",
        children: [
          { text: "Type " },
          { text: "@", bold: true },
          { text: " to open the inline combobox and mention someone." },
        ],
      },
    ],
  });

  return (
    <div className="w-full max-w-xl rounded-lg border bg-background p-2">
      <Plate editor={editor}>
        <PlateContent
          className="min-h-[160px] rounded-md px-3 py-2 text-sm outline-none"
          placeholder="Type @ to mention..."
        />
      </Plate>
    </div>
  );
}

