    },
    defaultVariants: { size: "md", variant: "default" },
  },
);

interface IButtonProps
  extends
    ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  render?:
    React.ReactElement | ((props: Record<string, any>) => React.ReactElement);
