      <form
        className="w-full max-w-sm"
        onSubmit={(e) => {
          e.preventDefault();
          if (checkEmail(email)) return;
          alert(`Invite sent to ${email}`);
        }}
      >
        <InlineValidation
          label="Work email"
          type="email"
          value={email}
          onChange={setEmail}
          validate={checkEmail}
          hint="Only used to send the invite."
          autoComplete="email"
          required
        />

