          "bg-card/80 backdrop-blur-md border border-border shadow-sm hover:shadow-2xl rounded-2xl overflow-hidden cursor-pointer",
          "transition-all duration-500 ease-[cubic-bezier(0.2,0.8,0.2,1)]",
