        <ExplodingInput
          content={emojis.map((e, i) => (
            <span key={i} style={{ fontSize: 22 }}>
              {e}
            </span>
          ))}
          count={s.count}
          gravity={s.gravity}
          direction={{ horizontal: "center", vertical: "top" }}
          scale={{
            value: 1,
            randomize: true,
            randomVariation: s.randomVariation,
          }}
          rotation={{ value: 0, animate: s.animate }}
        />
      </label>
    </div>
  );
}

