export function FadeSlideTabs({ text = "Fade Slide Tabs", className }: { text?: string; className?: string }) {
  const words = text.split(" ");
  return (
    <span className={cn("inline-flex flex-wrap", className)}>
      {words.map((word, i) => (
        <span
          key={`${word}-${i}`}
          className="animate-[fadeUp_.6s_ease-out_both]"
          style={{ animationDelay: `${i * 60}ms` }}
        >
          {word}&nbsp;
        </span>
      ))}
    </span>
  );
}

