  .holo-feed .holo-button {
    font-family: 'Orbitron', sans-serif;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    font-size: 0.8rem;
    color: var(--cyan-bright);
    padding: 0.5rem 1rem;
