"use client";

import * as React from "react";

export function ParticleAnimation({ className }: { className?: string }) {
  const ref = React.useRef<HTMLCanvasElement>(null);

  React.useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const gl = canvas.getContext("webgl");
    if (!gl) return;

    let raf = 0;
    const start = performance.now();
    const render = () => {
      const t = (performance.now() - start) / 1000;
      const { width, height } = canvas;
      gl.viewport(0, 0, width, height);
      gl.clearColor(0.02, 0.03, 0.08, 1);
      gl.clear(gl.COLOR_BUFFER_BIT);
      // Particle Animation: fragment shader driven by u_time (t)
      void t;
      raf = requestAnimationFrame(render);
    };
    render();
    return () => cancelAnimationFrame(raf);
  }, []);

  return <canvas ref={ref} className={className} style={{ width: "100%", height: "100%" }} />;
}

