components.componentCode:
"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

interface NextMetadataOutletProps extends React.HTMLAttributes<HTMLDivElement> {
  title?: string;
  description?: string;
}

export function NextMetadataOutlet({ title = "Next.MetadataOutlet", description, className, children, ...props }: NextMetadataOutletProps) {
  return (
    <div
      className={cn(
        "group relative overflow-hidden rounded-2xl border border-border bg-card p-6",
        "transition-all duration-300 hover:-translate-y-0.5 hover:border-primary/40 hover:shadow-xl hover:shadow-primary/5",
        className,
      )}
      {...props}
    >
      <div className="pointer-events-none absolute inset-0 opacity-0 transition-opacity duration-500 group-hover:opacity-100"
        style={{ background: "radial-gradient(400px circle at 50% 0%, color-mix(in oklch, var(--primary) 12%, transparent), transparent 70%)" }}
      />
      <div className="relative space-y-2">
        <h3 className="text-lg font-medium tracking-tight">{title}</h3>
        {description ? <p className="text-sm text-muted-foreground">{description}</p> : null}
        {children}
      </div>
    </div>
  );
}

